mapper.delete:
delete
from `corgi`.`corgi_blacklist`
where user_id = #{userId}
  and black_id = #{blackId}

mapper.select:
select user_id
from corgi_blacklist
where black_id = #{userId}

mapper.delete:
delete
from `corgi`.`corgi_blacklist`
where user_id = #{userId}
   or black_id = #{userId}

mapper.update:
update corgi_report
set report_status = #{status},
    `result`      = #{result}
where id = #{reportId}

mapper.select:
select r.id,
r.report_user_id reportUserId,
r.report_user_name reportUserName,
r.accuse_id accuseId,
r.accuse_type accuseType,
r.accuse_name accuseName,
r.report_status reportStatus,
r.`desc`,
r.reason,
r.ctime,
r.uptime,
r.`result`,
if(c.creator_id is null,r.accuse_id,c.creator_id) accuseUserId
from corgi_report r
left join corgi_activity_creator c on r.accuse_id = c.activity_id
where 1=1

    and r.report_status = #{report.reportStatus}


    and r.report_user_name = #{report.reportUserName}


    and r.report_user_id = #{report.reportUserId}


    and r.accuse_type = #{report.accuseType}


    and r.accuse_name = #{report.accuseName}


    and r.`desc` = #{report.desc}


    and r.`reason` = #{report.reason}


    and r.`accuse_id` = #{report.accuseId}

order by r.id desc
limit #{start}, #{size}

select count(1)
from corgi_report r
left join corgi_activity_creator c on r.accuse_id = c.activity_id
where 1=1

    and r.report_status = #{report.reportStatus}


    and r.report_user_name = #{report.reportUserName}


    and r.report_user_id = #{report.reportUserId}


    and r.accuse_type = #{report.accuseType}


    and r.accuse_name = #{report.accuseName}


    and r.`desc` = #{report.desc}


    and r.`reason` = #{report.reason}


    and (r.`accuse_id` = #{report.accuseId} or c.creator_id = #{report.accuseId})

select pic_url
from corgi_report_pic
where report_id = #{reportId}

select count(1)
from corgi_blacklist
where user_id = #{userId}
  and black_id = #{blockId}
